```go
package mcpserver

import (
	"context"
	"encoding/json"
	"sort"
	"strings"
	"time"

	"github.com/mark3labs/mcp-go/mcp"

	"github.com/entireio/cli/cmd/entire/cli/memoryloop"
)

const maxSearchResults = 10

type searchResponse struct {
	Memories    []memoryResult `json:"memories"`
	TotalActive int            `json:"total_active"`
	Mode        string         `json:"mode"`
}

type memoryResult struct {
	ID       string `json:"id"`
	Kind     string `json:"kind"`
	Title    string `json:"title"`
	Body     string `json:"body"`
	Why      string `json:"why,omitempty"`
	Strength int    `json:"strength"`
	Scope    string `json:"scope"`
	Outcome  string `json:"outcome,omitempty"`
	Score    int    `json:"score,omitempty"`
}

func handleSearchMemories(ctx context.Context, request mcp.CallToolRequest) (*mcp.CallToolResult, error) {
	state, err := checkModeGate(ctx)
	if err != nil {
		return mcp.NewToolResultError(err.Error()), nil
	}

	query := request.GetString("query", "")
	kindFilter := request.GetString("kind", "")
	scopeFilter := request.GetString("scope", "")
	statusFilter := request.GetString("status", "active")

	records := state.Store.Records
	totalActive := countByStatus(records, memoryloop.StatusActive)

	var results []memoryResult

	if query != "" {
		snapshot := memoryloop.Snapshot{
			Records:     records,
			MaxInjected: maxSearchResults,
		}
		report := memoryloop.PreviewSelection(snapshot, query, time.Now().UTC())
		for _, match := range report.Matches {
			r := match.Record
			if !matchesFilters(r, kindFilter, scopeFilter, statusFilter) {
				continue
			}
			results = append(results, memoryResult{
				ID:       r.ID,
				Kind:     string(r.Kind),
				Title:    r.Title,
				Body:     r.Body,
				Why:      r.Why,
				Strength: r.Strength,
				Scope:    string(r.ScopeKind),
				Outcome:  string(r.Outcome),
				Score:    match.Rationale.AdjustedScore,
			})
		}
	} else {
		filtered := filterRecords(records, kindFilter, scopeFilter, statusFilter)
		sort.Slice(filtered, func(i, j int) bool {
			if filtered[i].Strength != filtered[j].Strength {
				return filtered[i].Strength > filtered[j].Strength
			}
			return filtered[i].Title < filtered[j].Title
		})
		if len(filtered) > maxSearchResults {
			filtered = filtered[:maxSearchResults]
		}
		for _, r := range filtered {
			results = append(results, memoryResult{
				ID:       r.ID,
				Kind:     string(r.Kind),
				Title:    r.Title,
				Body:     r.Body,
				Why:      r.Why,
				Strength: r.Strength,
				Scope:    string(r.ScopeKind),
				Outcome:  string(r.Outcome),
			})
		}
	}

	resp := searchResponse{
		Memories:    results,
		TotalActive: totalActive,
		Mode:        string(state.Store.Mode),
	}
	if resp.Memories == nil {
		resp.Memories = []memoryResult{}
	}

	data, err := json.Marshal(resp)
	if err != nil {
		return mcp.NewToolResultError("failed to marshal response"), nil
	}

	return mcp.NewToolResultText(string(data)), nil
}

func matchesFilters(r memoryloop.MemoryRecord, kind, scope, status string) bool {
	if kind != "" && string(r.Kind) != kind {
		return false
	}
	if scope != "" && string(r.ScopeKind) != scope {
		return false
	}
	if status != "" && string(r.Status) != status {
		return false
	}
	return true
}

func filterRecords(records []memoryloop.MemoryRecord, kind, scope, status string) []memoryloop.MemoryRecord {
	var out []memoryloop.MemoryRecord
	for _, r := range records {
		if matchesFilters(r, kind, scope, status) {
			out = append(out, r)
		}
	}
	return out
}

func countByStatus(records []memoryloop.MemoryRecord, status memoryloop.Status) int {
	n := 0
	for _, r := range records {
		if r.Status == status {
			n++
		}
	}
	return n
}

// validStatuses defines which statuses are queryable via MCP.
func validSearchStatus(s string) bool {
	return s == "" || s == string(memoryloop.StatusActive) || s == string(memoryloop.StatusCandidate)
}
