```go
package mcpserver

import (
	"context"
	"encoding/json"
	"time"

	"github.com/mark3labs/mcp-go/mcp"

	"github.com/entireio/cli/cmd/entire/cli/memoryloop"
)

type saveResponse struct {
	ID        string `json:"id"`
	Status    string `json:"status"`
	Message   string `json:"message"`
	Duplicate bool   `json:"duplicate,omitempty"`
}

func handleSaveMemory(ctx context.Context, request mcp.CallToolRequest) (*mcp.CallToolResult, error) {
	state, err := checkModeGate(ctx)
	if err != nil {
		return mcp.NewToolResultError(err.Error()), nil
	}

	kind, err := request.RequireString("kind")
	if err != nil {
		return mcp.NewToolResultError("kind is required"), nil
	}
	title, err := request.RequireString("title")
	if err != nil {
		return mcp.NewToolResultError("title is required"), nil
	}
	body, err := request.RequireString("body")
	if err != nil {
		return mcp.NewToolResultError("body is required"), nil
	}
	why := request.GetString("why", "")
	scope := request.GetString("scope", "me")

	// Check for duplicates by fingerprint
	fp := memoryloop.FingerprintForRecord(memoryloop.Kind(kind), title, body)
	for _, r := range state.Store.Records {
		if r.Fingerprint == fp {
			resp := saveResponse{
				ID:        r.ID,
				Status:    string(r.Status),
				Message:   "A similar memory already exists (status: " + string(r.Status) + "). No duplicate created.",
				Duplicate: true,
			}
			data, _ := json.Marshal(resp)
			return mcp.NewToolResultText(string(data)), nil
		}
	}

	scopeKind := memoryloop.ScopeKindMe
	if scope == "repo" {
		scopeKind = memoryloop.ScopeKindRepo
	}

	now := time.Now().UTC()
	records, added, err := memoryloop.AddManualRecord(state.Store.Records, memoryloop.ManualRecordInput{
		Kind:      memoryloop.Kind(kind),
		Title:     title,
		Body:      body,
		ScopeKind: scopeKind,
	}, now)
	if err != nil {
		return mcp.NewToolResultError(err.Error()), nil
	}

	// Set why field if provided (AddManualRecord doesn't accept it)
	if why != "" {
		for i := range records {
			if records[i].ID == added.ID {
				records[i].Why = why
				break
			}
		}
	}

	state.Store.Records = records
	if err := memoryloop.SaveState(ctx, state); err != nil {
		return mcp.NewToolResultError("failed to save memory: " + err.Error()), nil
	}

	resp := saveResponse{
		ID:      added.ID,
		Status:  string(added.Status),
		Message: "Memory saved as candidate. Use `entire memory-loop activate " + added.ID + "` or the TUI to activate it.",
	}
	data, _ := json.Marshal(resp)
	return mcp.NewToolResultText(string(data)), nil
}
